create extension if not exists pgcrypto;
do $$ begin create type public.user_role as enum ('admin','staff'); exception when duplicate_object then null; end $$;
do $$ begin alter type public.user_role rename value 'staff' to 'user'; exception when invalid_parameter_value then null; when duplicate_object then null; end $$;
do $$ begin create type public.inventory_status as enum ('new','used','missing'); exception when duplicate_object then null; end $$;
create table if not exists public.profiles (id uuid primary key references auth.users(id) on delete cascade, full_name text not null default '', role public.user_role not null default 'user', clinic_name text not null default '', locale text not null default 'en' check (locale in ('en','es')), created_at timestamptz not null default now());
alter table public.profiles add column if not exists email text;
alter table public.profiles add column if not exists phone text;
alter table public.profiles add column if not exists avatar_url text;
alter table public.profiles add column if not exists status text not null default 'active';
do $$ begin alter table public.profiles add constraint profiles_status_check check (status in ('active','suspended')); exception when duplicate_object then null; end $$;
create table if not exists public.categories (id uuid primary key default gen_random_uuid(), slug text unique not null, name_en text not null, name_es text not null, color_hex text not null, sort_order integer not null default 0, is_active boolean not null default true);
insert into public.categories (slug,name_en,name_es,color_hex,sort_order) values ('surgery','Surgery','Cirugía','#9CC8F5',1),('periodontics','Periodontics','Periodoncia','#C4B2F2',2),('endodontics','Endodontics','Endodoncia','#F6B4CD',3),('orthodontics','Orthodontics','Ortodoncia','#D3E8A0',4),('restorative','Restorative','Restauración','#F9E29B',5),('prosthodontics','Prosthodontics','Prostodoncia','#F8C9A4',6),('hygiene','Hygiene','Higiene','#A5DFE8',7),('disposables','Disposables','Desechables','#B7DDB0',8),('anesthesia','Anesthesia','Anestesia','#F5B3A6',9),('other','Other','Otros','#D5D9E6',10) on conflict (slug) do update set name_en=excluded.name_en,name_es=excluded.name_es,color_hex=excluded.color_hex,sort_order=excluded.sort_order;
create table if not exists public.inventory_items (id uuid primary key default gen_random_uuid(), owner_id uuid not null references auth.users(id) on delete cascade, name text not null, category_id uuid references public.categories(id), quantity integer not null default 0 check(quantity >= 0), min_quantity integer not null default 1 check(min_quantity >= 0), expiry_date date, status public.inventory_status not null default 'new', created_at timestamptz not null default now());
alter table public.inventory_items add column if not exists category_id uuid references public.categories(id);
alter table public.inventory_items add column if not exists status public.inventory_status not null default 'new';
update public.inventory_items set category_id=(select id from public.categories where slug='other') where category_id is null;
create or replace function public.sync_inventory_status() returns trigger language plpgsql security invoker set search_path=public as $$ begin if new.quantity=0 then new.status:='missing'; elsif new.status='missing' then new.status:='new'; end if; return new; end $$;
drop trigger if exists inventory_status_sync on public.inventory_items; create trigger inventory_status_sync before insert or update of quantity,status on public.inventory_items for each row execute function public.sync_inventory_status();
create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path=public as $$ begin insert into public.profiles (id,email,full_name,role) values (new.id,new.email,coalesce(new.raw_user_meta_data->>'full_name',''),case when lower(new.email)='remgoficial@gmail.com' and new.email_confirmed_at is not null then 'admin'::public.user_role else 'user'::public.user_role end) on conflict (id) do nothing; return new; end $$;
drop trigger if exists on_auth_user_created on auth.users; create trigger on_auth_user_created after insert on auth.users for each row execute function public.handle_new_user();
create or replace function public.promote_admin_on_confirm() returns trigger language plpgsql security definer set search_path=public as $$ begin if new.email_confirmed_at is not null and lower(new.email)='remgoficial@gmail.com' then update public.profiles set role='admin',email=new.email where id=new.id; end if; return new; end $$;
drop trigger if exists on_auth_user_confirmed on auth.users; create trigger on_auth_user_confirmed after update of email_confirmed_at on auth.users for each row execute function public.promote_admin_on_confirm();
create or replace function public.protect_profile_columns() returns trigger language plpgsql set search_path=public as $$ begin if current_user in ('anon','authenticated') and (new.id is distinct from old.id or new.role is distinct from old.role or new.status is distinct from old.status or new.email is distinct from old.email) then raise exception 'protected profile columns cannot be changed'; end if; return new; end $$;
drop trigger if exists protect_profile_columns on public.profiles; create trigger protect_profile_columns before update on public.profiles for each row execute function public.protect_profile_columns();
update public.profiles p set email=u.email from auth.users u where u.id=p.id and p.email is null;
update public.profiles set role='admin' where id=(select id from auth.users where lower(email)='remgoficial@gmail.com' and email_confirmed_at is not null);
create index if not exists inventory_items_owner_idx on public.inventory_items(owner_id); create index if not exists inventory_items_category_idx on public.inventory_items(category_id);
create or replace function public.is_admin() returns boolean language sql security invoker set search_path=public as $$ select exists(select 1 from public.profiles where id=(select auth.uid()) and role='admin') $$;
create or replace function public.get_home_stats() returns table(slug text,name_en text,name_es text,color_hex text,units bigint,distinct_items bigint,missing_count bigint,expiring_count bigint,total_units bigint,total_missing bigint,total_expiring bigint) language sql security invoker set search_path=public as $$ with grouped as (select c.slug,c.name_en,c.name_es,c.color_hex,coalesce(sum(i.quantity),0)::bigint units,count(i.id)::bigint distinct_items,count(i.id) filter(where i.quantity=0)::bigint missing_count,count(i.id) filter(where i.expiry_date is not null and i.expiry_date between current_date and current_date+30)::bigint expiring_count from public.categories c left join public.inventory_items i on i.category_id=c.id and i.owner_id=(select auth.uid()) where c.is_active group by c.slug,c.name_en,c.name_es,c.color_hex,c.sort_order order by c.sort_order) select g.*,(select coalesce(sum(distinct_items),0) from grouped),(select coalesce(sum(missing_count),0) from grouped),(select coalesce(sum(expiring_count),0) from grouped) from grouped g; $$;
revoke all on function public.get_home_stats() from public;
grant execute on function public.get_home_stats() to authenticated;
revoke all on function public.handle_new_user() from public;
grant execute on function public.handle_new_user() to postgres;
alter table public.profiles enable row level security;
alter table public.categories enable row level security;
alter table public.inventory_items enable row level security;
alter table public.inventory_items drop column if exists category;
